  const mode=el.melodyMeter?.value||'4/4';
  if(mode!=='random'){songMeter=mode;songMeterBlock=Math.floor(bar/16);return mode;}
  const block=Math.floor(bar/(musicGoal()==='song'?SONG_FORM_LENGTH:16));
